@Module({
  imports: [SharedModule],
  controllers: [UsersController],
  providers: [UsersService],
  exports: [UsersService],
})
export class UsersModule {}

@Module({})
export class ConfigModule {
  static forRoot(options: Options): DynamicModule {
    return { module: ConfigModule, providers: [ConfigService], exports: [ConfigService] };
  }
}

@Module({})
export class DbModule {
  static forRootAsync(options: AsyncOptions): DynamicModule {
    return {
      module: DbModule,
      providers: [
        { provide: DB_OPTIONS, useFactory: options.useFactory, inject: options.inject || [] },
        DbService,
      ],
      exports: [DbService],
    };
  }
}

@Module({
  imports: [TypeOrmModule.forFeature([User, Order])],
  providers: [UserRepository],
})
export class UserPersistenceModule {}

@Module({
  imports: [forwardRef(() => AuthModule)],
  providers: [UsersService],
})
export class UsersModule {}

const providers = [AService, BService];

@Module({ providers })
export class BigModule {}

@Injectable()
export class PaymentService {
  constructor(
    @Inject('PAYMENT_GATEWAY') private readonly gateway: Gateway,
    private readonly repo: PaymentRepository,
  ) {}
}

@Controller('orders')
export class OrdersController {
  constructor(private readonly orders: OrdersService) {}
}

@Injectable()
export class CacheService {
  constructor(@Optional() @Inject('CACHE_TTL') private readonly ttl: number) {}
}

export class Helper {
  constructor(private readonly thing: Thing) {}
}
